INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261127-trump-thanksgiving-post-foes-immigrants', 'trump-thanksgiving-truth-social-post-attacks-critics-immigrants-economic-data', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'Trump uses Thanksgiving post to attack critics, immigrants and his own government''s economic data', 'In a 461-word Truth Social message on Thursday, Nov. 26, the president made claims about immigrants and federal statistics without offering evidence, Reuters reported.', 'President Trump used his Thanksgiving message on Thursday, Nov. 26, to go after liberals, immigrants and a federal statistics agency, Reuters reported in a story published by The Korea Times.

The 461-word post on Truth Social accused his own government of falsifying U.S. economic data, according to Reuters. The Commerce Department''s Bureau of Economic Analysis did not immediately respond to a request for comment, the agency reported.

## Claims without evidence

Trump also warned of unnamed people he said were seeking to impose Muslim religious law and to forcibly redistribute private property, and he described large numbers of immigrants and people of Somali descent as jobless or criminal, Reuters reported. He offered no evidence for those claims, some of which repeated earlier talking points, according to the report.

The president also defended his White House renovation projects, saying reporters and citizens had misunderstood them, Reuters said.

## Where he spent the holiday

Trump spent Thanksgiving at Trump International Golf Club in West Palm Beach, Florida, and was expected to call U.S. service members later in the day from Mar-a-Lago, according to Reuters.

The message came three weeks after the Nov. 3 midterm elections, in which his Republican Party lost heavily. Republicans will give up control of both chambers of Congress in January, Reuters noted.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Marine_One_at_Mar-a-Lago_(40548801803).jpg/1280px-Marine_One_at_Mar-a-Lago_(40548801803).jpg', 'Marine One at Mar-a-Lago, Palm Beach, Florida (file photo). Via Wikimedia Commons (Flickr 40548801803); editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-27.sql', 9, 1, 'newsroom-assistant', '2026-11-27T11:00:00.000Z', '2026-11-27T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261127-trump-thanksgiving-post-foes-immigrants-src1', 'bd-20261127-trump-thanksgiving-post-foes-immigrants', 'Trump uses Thanksgiving message to lash out at political foes, immigrants, federal government', 'https://www.koreatimes.co.kr/world/20261127/trump-uses-thanksgiving-message-to-lash-out-at-political-foes-immigrants-federal-government', 'The Korea Times (Reuters)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-27T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-27. Editor to confirm.', 'newsroom-assistant', '2026-11-27T11:00:00.000Z');
