INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261127-alikhan-declines-extend-dhs-ad-block', 'judge-alikhan-denies-dnc-preliminary-injunction-taxpayer-funded-dhs-ads-trump', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Judge lets block on taxpayer-funded pro-Trump ads expire, but says the DNC''s claim is likely to succeed', 'U.S. District Judge Loren AliKhan denied a preliminary injunction on Wednesday, Nov. 25, finding the Democrats could not show irreparable harm now that the midterms are over.', 'A federal judge in Washington on Wednesday, Nov. 25, declined to extend her order blocking government-funded TV ads that Democrats say promoted President Trump, The Epoch Times and Political.org reported.

U.S. District Judge Loren AliKhan denied the Democratic National Committee''s request for a preliminary injunction and let her temporary restraining order, first granted on Oct. 28, expire the same day, according to the reports. She found the party could no longer show irreparable harm because the Nov. 3 midterm elections were over, The Epoch Times reported. The DNC had pointed to the December runoffs in Louisiana and to elections in 2027 and 2028, but the judge was not persuaded, the outlet said.

## The ads

The DNC sued on Oct. 7 over ads that the Department of Homeland Security ran in the weeks before the midterms under a contract worth about $20 million, paid from money Congress set aside for border-security commemorations, according to The Epoch Times. Political.org reported that the party challenged at least 11 ads. The White House calls them public service announcements, the outlet said.

Raw Story reported that the White House budget office raised the funding from $500,000 to $20.5 million on the day it was requested, and that the ads ran on networks including Fox News, CNN and ABC and during football broadcasts.

## Not a win on the merits

The ruling covered only the emergency request. In a footnote, AliKhan wrote that nothing in it should cast doubt on the DNC''s likelihood of success, and she repeated that the party''s claim against the budget office and DHS is likely to succeed, Raw Story reported. A DNC spokesperson said the party was disappointed and would keep fighting, according to Political.org.

The two sides must propose next steps by Wednesday, Dec. 9, The Epoch Times reported. A similar suit from the Wisconsin Democratic Party is also before AliKhan, and on Nov. 20 Judge Jennifer Rochon in New York let her own block on the same ads expire, the outlet said.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/DHS_St_Elizabeth%27s_Building_1.jpg/1280px-DHS_St_Elizabeth%27s_Building_1.jpg', 'A building on the Department of Homeland Security''s St. Elizabeths campus in Washington (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-27.sql', 8, 0, 'newsroom-assistant', '2026-11-27T11:00:00.000Z', '2026-11-27T11:00:00.000Z');
