INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261127-supreme-court-immigration-agenda-dec-9', 'supreme-court-immigration-third-country-deportations-argument-december-9-asylum-detention', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Supreme Court sets up a term-long test of Trump''s immigration agenda, starting with third-country deportations on Dec. 9', 'The justices will also take up the asylum ban and mandatory detention of migrants, with decisions expected by late June, CNN reported.', 'The Supreme Court is preparing to rule on several pillars of President Trump''s immigration agenda this term, CNN reported on Wednesday, Nov. 25, in a story carried by KCRA.

The court will consider appeals over the administration''s asylum ban, mandatory detention of migrants and deportations to third countries, with decisions expected by late June, according to CNN. Arguments on third-country removals are set for Wednesday, Dec. 9; the asylum case is expected in the spring and the detention case next year, the report said.

## The first case

The Dec. 9 case is Department of Homeland Security v. D.V.D., SCOTUSblog reported. U.S. District Judge Brian Murphy in Massachusetts struck down the third-country removal policy in February, and the 1st Circuit largely upheld his ruling on Sept. 18, according to SCOTUSblog. On Sept. 29 the justices put Murphy''s order on hold in an unsigned order, allowing removals to continue until the case is decided; Justices Sotomayor, Kagan and Jackson said they would have denied the government''s request, the outlet reported.

## A mixed record so far

CNN noted that the 6-3 court has rejected Trump''s effort to upend birthright citizenship and limited his use of the 1798 Alien Enemies Act, while in June six-justice majorities let him end Temporary Protected Status for some migrants and limit asylum claims at the border.

A White House spokeswoman dismissed the ACLU''s argument that the policies are illegal, according to CNN.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Supreme_Court_of_the_United_States.jpg/1280px-Supreme_Court_of_the_United_States.jpg', 'The U.S. Supreme Court building in Washington (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-27.sql', 8, 0, 'newsroom-assistant', '2026-11-27T11:00:00.000Z', '2026-11-27T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261127-supreme-court-immigration-agenda-dec-9-src1', 'bd-20261127-supreme-court-immigration-agenda-dec-9', 'The Supreme Court is about to take a closer look at Trump''s immigration agenda', 'https://www.kcra.com/article/supreme-court-trump-immigration-agenda/74531418', 'KCRA (CNN)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-27T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-27. Editor to confirm.', 'newsroom-assistant', '2026-11-27T11:00:00.000Z');
