INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261127-bills-beat-chiefs-13-10-bass-57', 'bills-beat-chiefs-13-10-thanksgiving-tyler-bass-57-yard-field-goal', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Bills beat Chiefs 13-10 on Tyler Bass''s 57-yard field goal as time expires', 'Buffalo improved to 10-1 on Thanksgiving night, Thursday, Nov. 26, after a tipped punt set up the winning kick. The Bills visit the Patriots on Sunday, Dec. 6.', 'Tyler Bass kicked a 57-yard field goal as time expired, and the Buffalo Bills beat the Kansas City Chiefs 13-10 on Thanksgiving night, Thursday, Nov. 26, in Orchard Park, New York, The Boston Globe and ESPN reported.

## How it ended

With the score tied, Kansas City punted from its own 11 with 15 seconds left. Joe Andreessen got a hand on Matt Araiza''s punt, and Greg Dortch returned it 17 yards to the Chiefs'' 39 with 4 seconds to go, setting up Bass, according to the Globe. Bass had tied the game at 10 with a 54-yard kick about 12 minutes before the end, and Harrison Butker missed a 46-yard try wide right with 5:56 left, the Globe reported.

## The numbers

Josh Allen completed 10 of 21 passes for 81 yards with two interceptions, both in the red zone, ESPN reported. James Cook carried the Bills with 117 rushing yards and a 5-yard touchdown run; ESPN said he has now run for at least 75 yards and a touchdown in 10 straight games, an NFL record. Patrick Mahomes was 16 of 29 for 174 yards, and Emmett Johnson scored the Chiefs'' touchdown on a 1-yard run, according to the reports.

The Bills (10-1) lead the AFC, have won seven straight and matched their best start since 1991, the Globe reported. The Chiefs (8-3) saw a three-game winning streak end, ESPN said.

Buffalo plays at New England on Sunday, Dec. 6, at 4:25 p.m. ET on CBS, and Kansas City hosts the Los Angeles Rams on Thursday, Dec. 3, according to ESPN.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Highmark_Stadium,_autumn_2022.jpg/1280px-Highmark_Stadium,_autumn_2022.jpg', 'Highmark Stadium in Orchard Park, New York, in autumn 2022 (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-27.sql', 8, 0, 'newsroom-assistant', '2026-11-27T11:00:00.000Z', '2026-11-27T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261127-bills-beat-chiefs-13-10-bass-57-src1', 'bd-20261127-bills-beat-chiefs-13-10-bass-57', 'Tyler Bass hits 57-yard field goal as time expires to lift Bills past Chiefs on Thanksgiving', 'https://www.bostonglobe.com/2026/11/26/sports/bills-chiefs-thanksgiving-game-score/', 'The Boston Globe', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-27T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-27. Editor to confirm.', 'newsroom-assistant', '2026-11-27T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261127-bills-beat-chiefs-13-10-bass-57-src2', 'bd-20261127-bills-beat-chiefs-13-10-bass-57', 'Bills edge Chiefs with last-second FG in low-scoring battle', 'https://www.espn.com/nfl/story/_/id/50582828/2026-nfl-buffalo-bills-kansas-city-chiefs-thanksgiving', 'ESPN', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-27T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-27. Editor to confirm.', 'newsroom-assistant', '2026-11-27T11:00:00.000Z');
