INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261127-eagles-beat-cowboys-39-38-elliott-59', 'eagles-beat-cowboys-39-38-thanksgiving-comeback-jake-elliott-59-yard-field-goal', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Eagles rally from 21 down to beat Cowboys 39-38 on Jake Elliott''s 59-yard field goal', 'Joe Milton accounted for four touchdowns and DeVonta Smith had a career-high 200 receiving yards in Arlington, Texas, on Thursday, Nov. 26.', 'The Philadelphia Eagles came back from a 21-point deficit and beat the Dallas Cowboys 39-38 on Thanksgiving, Thursday, Nov. 26, in Arlington, Texas, when Jake Elliott made a 59-yard field goal with 2 seconds left, The Boston Globe reported.

## A fourth-down gamble

Leading by two with 55 seconds left, Cowboys coach Brian Schottenheimer went for it on fourth-and-1 from the Philadelphia 39 instead of punting, and Dak Prescott was sacked, according to the Globe. The Eagles, out of timeouts, moved to the Dallas 41 with 7 seconds left to set up Elliott''s kick, the Globe said.

Dallas had led by 21 in the third quarter and was still up 14 early in the fourth, the Globe reported. Brandon Aubrey missed a 40-yard field goal that would have stretched the lead to 11.

## How Philadelphia got back

Joe Milton threw touchdown passes of 50 and 45 yards to DeVonta Smith and ran for a 14-yard score, the Globe reported. Smith finished with a career-high 200 receiving yards. Kenny Moore II returned a punt blocked by Ty Robinson for a touchdown, and Makai Lemon''s 24-yard touchdown catch cut the lead to 38-36 with 2:10 left, according to the Globe.

For Dallas, Prescott threw two touchdown passes and ran for another, and Javonte Williams scored three times, the Globe reported. Eagles running back Saquon Barkley left in the first quarter with a stinger.

The Eagles improved to 4-7 and the Cowboys fell to 5-7, according to the Globe.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/AT%26T_Stadium_2022-08-24.jpg/1280px-AT%26T_Stadium_2022-08-24.jpg', 'AT&T Stadium in Arlington, Texas, on Aug. 24, 2022 (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-27.sql', 7, 0, 'newsroom-assistant', '2026-11-27T11:00:00.000Z', '2026-11-27T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261127-eagles-beat-cowboys-39-38-elliott-59-src1', 'bd-20261127-eagles-beat-cowboys-39-38-elliott-59', 'Joe Milton, DeVonta Smith lead Eagles to stunning comeback win over Cowboys on Thanksgiving', 'https://www.bostonglobe.com/2026/11/26/sports/eagles-cowboys-thanksgiving-game-score/', 'The Boston Globe', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-27T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-27. Editor to confirm.', 'newsroom-assistant', '2026-11-27T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261127-eagles-beat-cowboys-39-38-elliott-59-src2', 'bd-20261127-eagles-beat-cowboys-39-38-elliott-59', 'Eagles 39-38 Cowboys (Nov 26, 2026) Game Recap', 'https://www.espn.com/nfl/recap?gameId=401873080', 'ESPN', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-27T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-27. Editor to confirm.', 'newsroom-assistant', '2026-11-27T11:00:00.000Z');
