INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261127-bears-beat-lions-39-35-williams-odunze', 'bears-beat-lions-39-35-thanksgiving-caleb-williams-rome-odunze-nfc-north-lead', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Bears stun Lions 39-35 on Caleb Williams''s touchdown pass with 3 seconds left', 'Chicago took over first place in the NFC North in Detroit on Thursday, Nov. 26, despite 205 rushing yards and three touchdowns from Jahmyr Gibbs.', 'Caleb Williams threw a 6-yard touchdown pass to Rome Odunze with 3 seconds left, and the Chicago Bears beat the Detroit Lions 39-35 on Thanksgiving, Thursday, Nov. 26, in Detroit, The Boston Globe reported. It was Chicago''s first lead of the game, and the catch stood after a review, according to the Globe.

## The comeback

The Lions led by 11 midway through the fourth quarter after Jahmyr Gibbs''s 70-yard run for his third touchdown, the Globe reported. Chicago then got a Dillon Thieneman interception of Jared Goff and a failed Detroit fourth-and-4 try from the Bears'' 33, and Williams converted a fourth-and-1 run on the winning drive, according to the Globe. The Bears became the third team to rally from at least 11 points down in the fourth quarter to win on Thanksgiving, the Globe said.

## The numbers

Williams completed 30 of 44 passes for 345 yards and two touchdowns, and D''Andre Swift ran for 65 yards and a score and caught passes for 97 yards, the Globe reported. Gibbs ran for 205 yards on 21 carries. Goff was 25 of 36 for 313 yards with a touchdown pass to Sam LaPorta, and Amon-Ra St. Brown caught seven passes for 146 yards.

The Bears (9-2) have won six straight and broke a tie with the Lions (8-3) for first place in the NFC North, ending Detroit''s six-game winning streak, according to the Globe.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Detroit_December_2015_09_(Ford_Field).jpg/1280px-Detroit_December_2015_09_(Ford_Field).jpg', 'Ford Field in Detroit, December 2015 (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-27.sql', 6, 0, 'newsroom-assistant', '2026-11-27T11:00:00.000Z', '2026-11-27T11:00:00.000Z');
