INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261127-rams-beat-packers-26-13-corum-184', 'rams-beat-packers-26-13-thanksgiving-eve-blake-corum-184-yards', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Rams beat Packers 26-13 as Blake Corum runs for 184 yards in the first Thanksgiving Eve game', 'Los Angeles ran for 241 yards and held the ball for more than 40 minutes at SoFi Stadium on Wednesday, Nov. 25, for a fifth straight win.', 'Blake Corum ran 32 times for a career-high 184 yards and a touchdown, and the Los Angeles Rams beat the Green Bay Packers 26-13 on Wednesday, Nov. 25, in the NFL''s first Thanksgiving Eve game, Netflix''s Tudum and FOX Sports reported.

## Control on the ground

The Rams outrushed Green Bay 241 yards to 55 and held the ball for 40 minutes and 40 seconds, according to the FOX Sports box score. Green Bay committed three turnovers to the Rams'' one, and Los Angeles outgained the Packers 373 yards to 244.

Kyren Williams added a touchdown, and Brandon McManus made all four of his field goal attempts, FOX Sports reported. For Green Bay, Christian Watson caught four passes for 65 yards and a touchdown, and Jordan Love passed 3,000 yards for the season, according to the box score. The game drew 75,211 fans at SoFi Stadium in Inglewood, California.

The Rams (7-4) have won five straight and are second in the NFC West, and the Packers (6-5) are fourth in the NFC North, FOX Sports reported. Los Angeles visits Kansas City on Thursday, Dec. 3, and Green Bay hosts New Orleans on Sunday, Dec. 6, according to FOX Sports.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/SoFi_Stadium_2022.jpg/1280px-SoFi_Stadium_2022.jpg', 'SoFi Stadium in Inglewood, California, in 2022 (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-27.sql', 5, 0, 'newsroom-assistant', '2026-11-27T11:00:00.000Z', '2026-11-27T11:00:00.000Z');
